{
  "name": "builder_all_pairs_gap_softmax_simple",
  "intuition": "Reweight all pairs with a stable vectorized softmax over positive objective gaps without any import statements, using only PyTorch tensor ops. We preserve all pairs and clamp weights for numerical stability and robustness.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_softmax",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "softmax",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # If no pairs, return empty PrefBatch with matching pair_idx\n    if b_idx.numel() == 0:\n        pair_idx = (b_idx.to(torch.int64), winner_idx.to(torch.int64), loser_idx.to(torch.int64))\n        return PrefBatch(mode='pairwise', pair_idx=pair_idx, weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_softmax'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_pos = gap.clamp(min=0.0)\n    temperature = float(extra.get('weight_tau', 1.0))\n    gap_scaled = gap_pos / temperature\n    batch_size = objective.size(0)\n    device = objective.device\n    # Compute per-instance max gap for numerical stability\n    max_gap = gap_scaled.new_full((batch_size,), float('-inf'))\n    max_gap = max_gap.scatter_reduce(0, b_idx, gap_scaled, reduce='amax', include_self=True)\n    gap_shifted = gap_scaled - max_gap[b_idx]\n    exp_gap = gap_shifted.exp()\n    sum_exp = exp_gap.new_zeros(batch_size)\n    sum_exp = sum_exp.scatter_add(0, b_idx, exp_gap)\n    weight = exp_gap / (sum_exp[b_idx] + 1e-12)\n    weight = weight.clamp(min=0.25, max=4.0)\n    pair_idx = (b_idx.to(torch.int64), winner_idx.to(torch.int64), loser_idx.to(torch.int64))\n    return PrefBatch(mode='pairwise', pair_idx=pair_idx, weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_softmax'})"
}
