{
  "name": "builder_all_pairs_gap_sigmoid_003",
  "intuition": "Adjusting the pair weight scaling to use a sigmoid-based function for smoother and bounded weighting, which can improve stability and gradient behavior during reweight-only tuning. The sigmoid parameters are tuned to emphasize moderate gaps without over-penalizing large ones, and the weight family is set to 'gap_sigmoid' for consistency.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_sigmoid",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "gap_sigmoid"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "obj_z",
      "rank",
      "regret"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n    eps = 1e-6\n    raw = gap.clamp_min(0.0)\n    clamp_lo = float(extra.get('gap_clamp_lo', 0.1))\n    clamp_hi = float(extra.get('gap_clamp_hi', 4.0))\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)\n    # Use sigmoid-based scaling for weight\n    normalized_gap = raw / (raw.max() + eps)  # normalize to [0,1]\n    weight = torch.sigmoid(extra.get('gap_sigmoid_scale', 6.0) * (normalized_gap - 0.5))\n    weight = (weight + 1.0) / 2.0  # scale to [0,1]\n    weight = weight.clamp(0.0, 1.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n"
}

{
  "name": "reweight_combined_gap_sigmoid",
  "intuition": "Combines the gap_linear weighting from parent 1 with a sigmoid-based monotone transform to produce a smooth, bounded, and expressive pair weight function that emphasizes moderate gaps while suppressing outliers. Preserves the all_pairs topology and pairwise structure, while introducing a flexible and stable weighting scheme suitable for reweight_only crossover.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_sigmoid",
    "constraint_family": "clamp_only"
  },
  "operators_used": ["all_pairs", "sigmoid", "mul", "add", "clamp"],
  "implementation_hint": {
    "expects": ["objective", "log_prob", "obj_z", "rank", "regret"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Use existing pair indices\n    b_idx, winner_idx, loser_idx = feature_cache['pair_idx'][0], feature_cache['pair_idx'][1], feature_cache['pair_idx'][2]\n    # Compute gap as in parent\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Apply sigmoid transform to gap for smooth weighting\n    raw_weight = ops.sigmoid(ops.mul(2.0, gap))  # scale gap to control steepness\n    weight = ops.clamp(raw_weight, 0.0, 1.0)  # ensure bounded between 0 and 1\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'reweight_combined_gap_sigmoid', 'weight_family': 'gap_sigmoid'})"
}

{
  "name": "builder_all_pairs_gap_sigmoid_010",
  "intuition": "rule_based:all_pairs:reweight:gap_sigmoid emphasizing moderate gaps with smooth weighting",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_sigmoid",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "sigmoid"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    objective = feature_cache['objective']\n    # fixed all pairs mask: winner objective < loser objective\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_clamped = gap.clamp_min(0.0)\n    tau = float(extra.get('weight_tau', 1.0))\n    raw = torch.sigmoid(gap_clamped / tau) - 0.5\n    # scale raw to [0,1] range\n    raw = raw * 2.0\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n"
}

