  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'reweighted_gap_linear_clamped', 'weight_family': 'gap_sigmoid_clamp'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    raw_weight = gap\n    # Transform: emphasize moderate gaps with sigmoid, then clamp\n    tau = float(extra.get('weight_tau', 1.0))\n    sigmoid_weight = 1.0 / (1.0 + (-raw_weight / tau).exp())\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = sigmoid_weight.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'reweighted_gap_linear_clamped', 'weight_family': 'gap_sigmoid_clamp'})"
