{
  "name": "all_pairs_gap_linear_smooth_tiezone",
  "intuition": "Smoothly suppress small gaps via a soft threshold and replace hard clamping with smooth scaled weighting to improve gradient stability.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear_smooth_tiezone",
    "constraint_family": "tie_zone_suppression"
  },
  "operators_used": [
    "all_pairs",
    "gap_linear",
    "relu",
    "smoothstep",
    "mul"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear_smooth_tiezone'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    raw = (gap).relu()\n    tie_zone_thresh = float(extra.get('tie_zone_thresh', 0.1))\n    tie_zone_smooth = float(extra.get('tie_zone_smooth', 0.05))\n    # Smooth suppression: weights transition smoothly from 0 at threshold to full beyond threshold + smooth\n    x = (raw - tie_zone_thresh) / (tie_zone_smooth + 1e-9)\n    smooth_mask = (x.clamp(0.0,1.0)) ** 2 * (3 - 2 * (x.clamp(0.0,1.0)))  # smoothstep cubic\n    weighted_gap = raw * smooth_mask\n    clamp_lo = float(extra.get('clamp_lo', 0.25))\n    clamp_hi = float(extra.get('clamp_hi', 4.0))\n    # Replace hard clamp with scaled linear stretch inside clamp range\n    weight = (weighted_gap - clamp_lo).clamp_min(0.0) / (clamp_hi - clamp_lo)  # scale to [0,1]\n    weight = weight.clamp(0.0, 1.0) * (clamp_hi - clamp_lo) + clamp_lo  # linearly scale back\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear_smooth_tiezone'})"
}

