{
  "name": "reweight_gap_linear_softclamp",
  "intuition": "Reweight all pairs with gap-linear weighting softened by a smooth quadratic clamp that gently limits extreme weights without hard cutoff, preserving gap linearity and differentiable transitions.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear_softclamp",
    "constraint_family": "soft_quadratic_clamp"
  },
  "operators_used": [
    "all_pairs",
    "sub",
    "clamp_min",
    "mul",
    "add"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear_softclamp'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap = gap.clamp_min(0.0)\n    clamp_lo = float(extra.get('clamp_lo', 0.1))\n    clamp_hi = float(extra.get('clamp_hi', 4.0))\n    # softly clamp: transition quadratic penalty outside [clamp_lo, clamp_hi]\n    weight = gap.clone()\n    # below clamp_lo: quadratic penalty toward zero\n    below_mask = (weight < clamp_lo).to(weight.dtype)\n    weight = (weight * (1 - below_mask) + \n              (clamp_lo * weight / clamp_lo**2 * weight) * below_mask)\n    # above clamp_hi: quadratic penalty diminishing beyond clamp_hi\n    above_mask = (weight > clamp_hi).to(weight.dtype)\n    excess = weight - clamp_hi\n    weight = (weight * (1 - above_mask) + \n              (clamp_hi + excess - 0.5 * excess * excess) * above_mask)\n    # ensure nonnegative after soft clamp\n    weight = weight.clamp_min(0.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear_softclamp'})"
}

