      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    # Retrieve objective values\n    objective = feature_cache['objective']\n    # Identify pairs where winner's objective is less than loser's\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid_linear'})\n    # Calculate the gap between loser's and winner's objectives\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Apply clamp for numerical stability\n    raw_gap = gap.clamp_min(0.0)\n    # Fetch tunable thresholds, defaulting to 0.1 and 1.0\n    band_lower = float(extra.get('band_lower', 0.1))\n    band_upper = float(extra.get('band_upper', 1.0))\n    # Normalize gap within band thresholds\n    ramp = (raw_gap - band_lower) / (band_upper - band_lower)\n    # Clamp to [0,1] range\n    ramp = ramp.clamp(0.0, 1.0)\n    # Create bandpass weight emphasizing mid-band regions\n    # Use quadratic for smoother peak at 0.5\n    bandpass_weight = ramp * (1.0 - ramp) * 4.0  # Peak at 0.5\n    bandpass_weight = bandpass_weight.clamp(0.0, 1.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=bandpass_weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid_linear'})"
